// Escolhe, entre os e-mails novos da Caixa de Entrada, os que parecem pedir informação de pedidos
// (pedido, TRF, cotação, compra, solicitação, produção, prazo, NF). Pula os já vistos, os automáticos,
// os que o dono mesmo mandou e os que ele já respondeu. Devolve no máximo N por execução, os mais antigos primeiro.
const cfg = $('Configuração').first().json;
const eu = $('Quem sou eu').first()?.json ?? {};
const meuEmail = String(eu.mail || eu.userPrincipalName || '').trim().toLowerCase();
const meuDominio = meuEmail.includes('@') ? meuEmail.split('@')[1] : '';
const lista = $('Buscar e-mails novos').first()?.json?.value;
const emails = Array.isArray(lista) ? lista : [];
const vistos = new Set(
  $('Já processados')
    .all()
    .map((i) => String(i.json.message_id ?? ''))
    .filter(Boolean),
);
const maximo = Math.min(Math.max(Number(cfg.max_por_execucao) || 5, 1), 10);

const normalizar = (s) =>
  String(s ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();

const AUTOMATICO = /^(no-?reply|nao-?responda|naoresponda|do-?not-?reply|mailer-daemon|postmaster|bounce|notifica|notification|alerta?s?|newsletter|news|marketing|info@|mkt)/;
const ASSUNTO_AUTOMATICO = /^(resposta automatica|automatic reply|auto-?reply|out of office|fora do escritorio|ausencia|aceito:|recusado:|provisorio:|accepted:|declined:|tentative:|convite:|invitation:|updated invitation|convite atualizado|cancelado:|canceled:|entrega nao realizada|undeliverable|mail delivery)/;
const FORTES = /\b(pedidos?|trf|transferencias?|cotac(ao|oes)|orcamentos?|solicitac(ao|oes) de compras?|requisic(ao|oes)|ordens? de compra|ordens? de producao|faturamento|nota fiscal|notas fiscais|previsao de entrega|prazo de entrega|status do pedido|posicao do pedido|situacao do pedido)\b/;
const SIGLAS = /\b(op|oc|sc|nf|nfe|nf-e)\s*(n[o°º]?\.?\s*)?:?\s*\d{3,}/;
const FRACOS = /\b(prazo|entrega|previsao|status|posicao|situacao|atraso|atrasad[oa]s?|embarque|expedicao|separacao|estoque|disponibilidade|material|materiais|producao|faturad[oa]s?)\b/;
const NUMERO = /\b\d{4,}\b/;

// Corta o histórico citado (respostas anteriores) e deixa só a mensagem nova.
function mensagemNova(texto) {
  const linhas = String(texto ?? '').replace(/\r/g, '').split('\n');
  const corte = linhas.findIndex(
    (l, i) =>
      i > 0 &&
      (/^\s*(-{2,}\s*(original message|mensagem original)|_{8,})/i.test(l) ||
        /^\s*(de|from):\s.+/i.test(l) && linhas.slice(i + 1, i + 4).some((p) => /^\s*(enviad[oa]|sent|para|to|data|date|assunto|subject):/i.test(p)) ||
        /^\s*(em|on)\s.+(escreveu|wrote):\s*$/i.test(l)),
  );
  const nova = (corte > 0 ? linhas.slice(0, corte) : linhas).join('\n');
  return nova.replace(/\n{3,}/g, '\n\n').trim().slice(0, 4000);
}

const endereco = (r) => String(r?.emailAddress?.address ?? '').trim().toLowerCase();
const nome = (r) => String(r?.emailAddress?.name ?? '').trim();

const candidatos = [];
for (const e of emails) {
  const chave = String(e.internetMessageId || e.id || '');
  if (!chave || vistos.has(chave)) continue;
  if (/eventMessage/i.test(String(e['@odata.type'] ?? ''))) continue;

  const remetente = endereco(e.from) || endereco(e.sender);
  if (!remetente || (meuEmail && remetente === meuEmail)) continue;
  if (AUTOMATICO.test(remetente)) continue;

  const assunto = String(e.subject ?? '').trim();
  const assuntoNorm = normalizar(assunto).replace(/^((re|res|fw|fwd|enc|rv|tr)\s*:\s*)+/, '');
  if (ASSUNTO_AUTOMATICO.test(assuntoNorm)) continue;

  const verbo = (e.singleValueExtendedProperties ?? []).find((p) => /0x1081/i.test(String(p.id)));
  if (verbo && ['102', '103', '104'].includes(String(verbo.value))) continue; // já respondido ou encaminhado

  const texto = mensagemNova(e.body?.content ?? e.bodyPreview ?? '');
  const tudo = normalizar(`${assunto}\n${texto}`);
  const relevante = FORTES.test(tudo) || SIGLAS.test(tudo) || (FRACOS.test(tudo) && NUMERO.test(tudo));
  if (!relevante) continue;

  const para = (e.toRecipients ?? []).map(endereco);
  const copia = (e.ccRecipients ?? []).map(endereco);
  const dominio = remetente.split('@')[1] ?? '';
  candidatos.push({
    chave,
    id: e.id,
    assunto: assunto || '(sem assunto)',
    remetente_nome: nome(e.from) || remetente,
    remetente_email: remetente,
    externo: meuDominio ? dominio !== meuDominio : true, // sem saber o domínio do dono, trata como externo (mais cuidado)
    so_em_copia: Boolean(meuEmail) && !para.includes(meuEmail) && copia.includes(meuEmail),
    recebido_em: e.receivedDateTime
      ? DateTime.fromISO(e.receivedDateTime).setZone('America/Sao_Paulo').toFormat("dd/MM/yyyy 'às' HH:mm")
      : '',
    recebido_iso: e.receivedDateTime ?? '',
    texto: texto || '(e-mail sem texto)',
  });
}

candidatos.sort((a, b) => String(a.recebido_iso).localeCompare(String(b.recebido_iso)));
return candidatos.slice(0, maximo).map((json) => ({ json }));

// Lê o JSON que a Kira devolveu para um e-mail e junta com os dados do e-mail.
const email = $('Separar e-mails').item.json;
const bruto = String($json.output ?? $json.text ?? '').trim();

function extrairJson(texto) {
  const semCerca = texto.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  try {
    return JSON.parse(semCerca);
  } catch (erro) {
    const inicio = semCerca.indexOf('{');
    const fim = semCerca.lastIndexOf('}');
    if (inicio >= 0 && fim > inicio) {
      try {
        return JSON.parse(semCerca.slice(inicio, fim + 1));
      } catch (erro2) {
        return null;
      }
    }
    return null;
  }
}

const r = extrairJson(bruto) ?? {};
const resposta = String(r.resposta ?? '').trim();
const responder = r.responder === true || r.responder === 'true';
const confirmar = (resposta.match(/\[confirmar\]/gi) ?? []).length;

return {
  json: {
    ...email,
    responder: responder && resposta.length > 0,
    motivo: String(r.motivo ?? (bruto ? 'resposta fora do formato' : 'sem resposta da IA')).slice(0, 200),
    resumo: String(r.resumo ?? '').trim().slice(0, 300),
    resposta,
    confirmar,
    consultou: r.consultou === true || r.consultou === 'true',
  },
};

// Junta o resultado do rascunho (criado ou erro) com o e-mail, para registrar e avisar.
// O sub-workflow do rascunho devolve a "referencia" (a chave do e-mail) para achar o e-mail certo.
const emails = $('Interpretar resposta').all().map((i) => i.json);
let email = emails.find((e) => e.chave && e.chave === $json.referencia);
if (!email) {
  try {
    email = $('Interpretar resposta').item.json;
  } catch (erro) {
    email = {};
  }
}
const criado = Boolean($json.id) && !$json.error && $json.ok !== false;
return {
  json: {
    chave: email.chave,
    assunto: email.assunto,
    remetente_nome: email.remetente_nome,
    remetente_email: email.remetente_email,
    externo: email.externo,
    resumo: email.resumo,
    confirmar: email.confirmar,
    status: criado ? 'rascunho' : 'erro',
    motivo: criado ? 'rascunho criado' : `falha ao criar o rascunho: ${String($json.error?.message ?? $json.error ?? 'sem detalhe').slice(0, 150)}`,
    link: criado ? String($json.webLink ?? '') : '',
    aviso_assinatura: criado ? String($json.aviso ?? '') : '',
  },
};

// Monta o aviso do Telegram (HTML seguro) para cada e-mail com rascunho criado ou que falhou.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const e = $json;
const quem = e.remetente_nome && e.remetente_nome !== e.remetente_email ? `${e.remetente_nome} (${e.remetente_email})` : e.remetente_email;

let html;
if (e.status === 'rascunho') {
  const linhas = [
    '📝 <b>Deixei uma resposta pronta no Outlook</b>',
    `<b>De:</b> ${esc(quem)}`,
    `<b>Assunto:</b> ${esc(e.assunto)}`,
  ];
  if (e.resumo) linhas.push(`<b>Resposta:</b> ${esc(e.resumo)}`);
  if (e.confirmar > 0) linhas.push(`⚠️ ${e.confirmar} ${e.confirmar === 1 ? 'ponto marcado' : 'pontos marcados'} como [confirmar].`);
  if (e.externo) linhas.push('🔒 Remetente de fora da empresa: confira os dados antes de enviar.');
  if (e.aviso_assinatura) linhas.push(`🖊️ Assinatura: ${esc(e.aviso_assinatura)}.`);
  linhas.push('Está em Rascunhos, na conversa do e-mail. Revise e envie você mesmo; eu não envio nada.');
  if (/^https:\/\//.test(e.link)) linhas.push(`<a href="${esc(e.link)}">Abrir o rascunho</a>`);
  html = linhas.join('\n');
} else {
  html = [
    '⚠️ <b>Não consegui deixar a resposta pronta</b>',
    `<b>De:</b> ${esc(quem)}`,
    `<b>Assunto:</b> ${esc(e.assunto)}`,
    'Se quiser, peça para mim no chat: "Kira, prepare a resposta para esse e-mail".',
  ].join('\n');
}
return { json: { html } };

// A Kira (IA) falhou para este e-mail. Se foi limite de uso ou instabilidade, não registra:
// o e-mail volta na próxima execução. Outros erros ficam registrados para não repetir sem fim.
const email = $('Separar e-mails').item.json;
const erro = String($json.error?.message ?? $json.error ?? $json.message ?? '').slice(0, 300);
const temporario = /429|quota|resource.?exhausted|rate.?limit|limite|503|502|500|overloaded|unavailable|timeout|timed out|ECONNRESET|socket hang up/i.test(erro);
if (temporario) return [];
return [
  {
    json: {
      chave: email.chave,
      assunto: email.assunto,
      remetente_nome: email.remetente_nome,
      remetente_email: email.remetente_email,
      status: 'erro',
      motivo: `falha da IA: ${erro || 'sem detalhe'}`.slice(0, 200),
    },
  },
];
